        'intune_types_hint' => 'Intune કહે છે કે દરેક ડિવાઇસ શું છે. જે એસેટનો કોઈ પ્રકાર નથી તેને તેના ડિવાઇસના પ્રકાર માટે અહીં પસંદ કરેલો પ્રકાર મળે છે; કોઈએ પસંદ કરેલો પ્રકાર ક્યારેય બદલાતો નથી. જ્યારે Intune ને ખબર ન હોય, ત્યારે iOS, iPadOS અને Android ડિવાઇસને Other mobile device પ્રકાર મળે છે; કમ્પ્યુટરને પ્રકાર વિના છોડવામાં આવે છે. Create હજુ No type પર સેટ દરેક પ્રકારને તેના નામ પરથી સૂચવાતો પ્રકાર આપે છે, અથવા તેના નામ પરથી નવો પ્રકાર બનાવે છે, અને મેપિંગ સાચવે છે.',
