        'intune_follow_primary_user_label' => 'પ્રાઇમરી યુઝરના ફેરફારોને અનુસરો',
        'intune_follow_primary_user_hint' => 'જ્યારે Intune માં ડિવાઇસનો પ્રાઇમરી યુઝર બદલાય, ત્યારે તેની એસેટ નવી વ્યક્તિ પાસે ખસે છે - કોઈપણ હેન્ડઓવરની જેમ કસ્ટડી ટ્રેઇલમાં નોંધાય છે. ફક્ત તે એસેટ જે Intune એ પોતે કોઈને આપી હોય: અહીં પસંદ કરેલો ધારક ક્યારેય ખસેડાતો નથી. ઉપરના સેટિંગની જરૂર છે. તમે ચાલુ કરો ત્યાં સુધી બંધ.',
        'intune_assign_primary_user_hint' => 'જે એસેટ કોઈની પાસે નથી તે Intune માં તેના ડિવાઇસના પ્રાઇમરી યુઝરને આપવામાં આવે છે, Entra object id દ્વારા મેળવીને - જેના માટે Microsoft Entra ID માંથી લોકો ઇમ્પોર્ટ થયેલા હોવા જોઈએ (System → Authentication). જે એસેટનો પહેલેથી ધારક છે તે ક્યારેય બદલાતી નથી, અને કોઈને અનસાઇન કરાતું નથી. તમે ચાલુ કરો ત્યાં સુધી બંધ.',
        'intune_assign_primary_user_when' => 'તે દરેક Intune સિંક અને દરેક Entra ઇમ્પોર્ટ પછી ચાલે છે, એટલે બેમાંથી કયું પહેલાં ચાલે તેનાથી ફરક પડતો નથી.',
        'tab_asset_tags' => 'એસેટ ટેગ',
