        'asset_label_logo_restrictions_hint' => 'લોગો ફોર્મેટ: ફક્ત PNG અથવા JPG, વધુમાં વધુ 2 MB. ચોરસ, ઘાટા અથવા ઊંચા કોન્ટ્રાસ્ટવાળા લોગો શ્રેષ્ઠ કામ કરે છે. વિશ્વસનીય સ્કેનિંગ માટે Error Correction Level H (30% રિડન્ડન્સી) સાથે QR કોડના કેન્દ્રમાં 22% સુધી સ્કેલ કરાય છે.',
