        'protect_check' => 'જ્યારે કોઈ ટૂલ દ્વારા રિપોર્ટ થતી એસેટનું નામ, ઉત્પાદક અથવા મોડેલ સંપાદિત કરે, ત્યારે તેને ઓવરરાઇટ થતું અટકાવવા સુરક્ષિત કરો',
        'protect_hint' => 'નહિતર એજન્ટ અથવા Intune આગામી રિપોર્ટમાં પોતાની કિંમત પાછી મૂકી દે છે. કોઈપણ કિંમતને તેની બાજુના તાળા વડે જાતે પણ સુરક્ષિત અથવા મુક્ત કરી શકાય છે.',
        'stale_days_label' => 'ઇન્વેન્ટરી આટલા (દિવસ) પછી જૂની ગણાય છે',
        'stale_days_hint' => 'આના કરતાં જૂની ઇન્વેન્ટરી યાદી એસેટ પર કેસરી રંગમાં બતાવાય છે - તેની યાદી ઉપર અને Inventory sources પેનલમાં. તેને તમારા સ્રોતો કેટલી વાર રિપોર્ટ કરે છે તેની સાથે મેળ ખાતી રાખો: રોજ ચાલતા એજન્ટ માટે 7 દિવસ યોગ્ય છે.',
        'reconciliation_heading' => 'એસેટ ડિસ્કવરી અને રિકન્સિલિએશન',
        'reconciliation_intro' => 'તમામ ઑટોમેટેડ હાર્ડવેર ડિસ્કવરી સ્રોતો (PowerShell ઇન્વેન્ટરી એજન્ટ, Intune અને ભવિષ્યના ડિસ્કવરી કનેક્ટર્સ) માટે આઇડેન્ટિટી રિકન્સિલિએશન નિયમો અને અવગણાયેલા સીરિયલ નંબર ગોઠવો.',
