        'leave_unchanged' => '(બદલ્યા વિના રહેવા દો)',
        'stocktake_hint' => 'તમે સ્કેન કરો તે દરેક એસેટને આ મળે છે. જે એસેટ પહેલેથી આ રીતે સેટ છે તેને જોવાયેલી ગણીને છોડી દેવાય છે, જેથી તેના ઇતિહાસમાં નકામું કંઈ ન ઉમેરાય.',
        'torch' => 'લાઇટ',
