        'start_camera' => 'કૅમેરા શરૂ કરો',
        'manual_label' => 'અથવા ટેગ, સીરિયલ કે હોસ્ટનામ ટાઇપ કરો',
        'manual_hint' => 'કૅમેરા બ્લોક હોય, લેબલ ખરાબ થયું હોય, અથવા સાધન પર ફક્ત ઉત્પાદકનો પોતાનો બારકોડ હોય ત્યારે કામ આવે છે.',
        'session_heading' => 'આ સેશનમાં સ્કેન કરેલું',
        'cam_insecure' => 'કૅમેરાને સુરક્ષિત (https) સરનામું જોઈએ.<br>તેના બદલે નીચે ટેગ કે સીરિયલ ટાઇપ કરો, અથવા આ ઇન્સ્ટોલ https પર ખોલો.',
        'cam_unsupported' => 'આ બ્રાઉઝરમાં કૅમેરા સપોર્ટ નથી. નીચે ટેગ કે સીરિયલ ટાઇપ કરો.',
        'cam_denied' => 'કૅમેરાની પરવાનગી નકારાઈ.<br>તમારા બ્રાઉઝર સેટિંગ્સમાં તેને મંજૂરી આપો, અથવા નીચે ટેગ કે સીરિયલ ટાઇપ કરો.',
        'cam_failed' => 'કૅમેરા શરૂ કરી શકાયો નહીં. નીચે ટેગ કે સીરિયલ ટાઇપ કરો.',
        'looking_up' => 'શોધાઈ રહ્યું છે…',
