        'not_yours' => 'એ લેબલ તમને દેખાતી એસેટનું નથી. તે બીજી કંપનીનું હોઈ શકે.',
        'no_match' => '{q} સાથે કંઈ મેળ ખાતું નથી',
        'server_error' => 'સર્વર સુધી પહોંચી શકાયું નહીં — {message}',
        'already_scanned' => 'પહેલેથી સ્કેન કરેલું — હજુ {status}',
        'unchanged' => 'બદલાયું નથી',
        'seen_nothing_set' => 'જોવાયું — સેટ કરવા માટે હજુ કંઈ પસંદ કર્યું નથી',
        'already_set' => 'પહેલેથી સેટ છે — જોવાયેલું ગણ્યું',
