    'help' => [
        'missing' => [
            'nav' => 'ખૂટતી માહિતી',
            'heading' => 'ખૂટતી માહિતી',
            'intro' => 'એસેટ પહેલા દિવસે તમે જાણો છો તે સાથે નોંધી શકાય છે - તેનું નામ, પ્રકાર અને સીરિયલ - અને બાકીનું પછી ભરી શકાય. <strong>અપેક્ષિત માહિતી</strong> કહે છે કે દરેક એસેટ પ્રકારમાં આખરે કયા ફીલ્ડ હોવા જોઈએ, અને <strong>ખૂટતી માહિતી</strong> ફીલ્ડના નામ સાથે એવી દરેક એસેટ યાદીમાં આપે છે જેમાં તે ખૂટે છે. કંઈ ક્યારેય નકારાતું નથી: પેજ, ઇમ્પોર્ટ, REST API અને ઇન્વેન્ટરી એજન્ટ પહેલાની જેમ જ સાચવે છે.',
            'p1' => '<strong>ફીલ્ડ પસંદ કરો:</strong> સેટિંગ્સ -> એસેટ પ્રકારો -> એક પ્રકાર -> <strong>અપેક્ષિત માહિતી</strong>. બિલ્ટ-ઇન ફીલ્ડ (ઓળખ, બ્રાન્ડ અને મોડેલ, નાણાકીય) અને તે પ્રકાર સાથે જોડાયેલા ફીલ્ડ સેટમાંના કોઈપણ કસ્ટમ ફીલ્ડને ટિક કરો. પ્રકારના લેઆઉટમાં સેક્શન છુપાવવાથી તેના ફીલ્ડ લાગુ પડતા નથી એવું બનતું નથી.',
            'p2' => '<strong>યાદી પર કામ કરો:</strong> પ્રકાર કંઈક અપેક્ષા રાખે કે તરત હેડરમાં <strong>ખૂટતી માહિતી</strong> બટન દેખાય છે. પ્રકાર, સેક્શન (દા.ત. નાણાકીય) અથવા ફીલ્ડ પ્રમાણે ફિલ્ટર કરો; ખોલવા માટે એસેટ પર ક્લિક કરો. ફીલ્ડ - ગમે ત્યાં - ભરો અને તે તરત યાદીમાંથી જતું રહે છે; ખાલી કરો અને તે પાછું આવે છે.',
            'p3' => '<strong>ખૂટે છે</strong> એટલે ખાલી: કોઈ કિંમત નહીં, ખાલી ટેક્સ્ટ અથવા કોઈ પસંદગી નહીં. 0 ખર્ચ કે "ના" ભરેલું ગણાય છે - તપાસ એ છે કે કિંમત છે કે નહીં, તે સાચી છે કે નહીં તે નહીં. નિવૃત્ત એસેટ યાદીમાં આવતી નથી.',
            'p4' => '<strong>લાગુ પડતું નથી</strong> એક એસેટ માટે એક ફીલ્ડને બાજુએ મૂકે છે - દાખલા તરીકે, ખરીદ ખર્ચ વગરનું દાનમાં મળેલું લેપટોપ. તે ફીલ્ડમાં કશું લખતું નથી, એસેટના ઇતિહાસમાં નોંધાય છે, અને એસેટ પર <strong>પૂર્વવત્ કરો</strong> સાથે દેખાય છે. તેને એસેટ્સની લખવાની ઍક્સેસ જોઈએ.',
        ],
        'retired' => [
            'nav' => 'નિવૃત્ત એસેટ',
            'heading' => 'નિવૃત્ત એસેટ',
            'intro' => 'જે સાધનો એસ્ટેટમાંથી નીકળી ગયા છે - નિકાલ થયો, ડિકમિશન થયા, અથવા બીજી સંસ્થાને સોંપાયા - તે રેકોર્ડ તરીકે રહે છે, પણ સક્રિય એસેટ તરીકે ગણાતા નથી.',
            'p1' => '<strong>"નિવૃત્ત" ને શું કહેવાય તે પસંદ કરો.</strong> <strong>સેટિંગ્સ &rarr; એસેટ સ્થિતિઓ</strong> હેઠળ, સ્થિતિ ("Retired", "Disposed", "Transferred") સંપાદિત કરો અને <strong>નિવૃત્ત</strong> ટિક કરો. તમે ન કરો ત્યાં સુધી કશું નિવૃત્ત થતું નથી.',
            'p2' => 'એસેટને તે સ્થિતિ આપીને <strong>એસેટ નિવૃત્ત કરો</strong>. તેના પર તારીખની મહોર લાગે છે, તમે કારણ ઉમેરી શકો છો ("શિક્ષણ મંત્રાલયને સોંપાયું"), અને તે એસેટ યાદી, ટેબલ, ડેશબોર્ડ, Watchtower, વોરંટી અને લીઝ ચેતવણીઓ અને કૅલેન્ડરમાંથી જતી રહે છે. તેને ફરી સામાન્ય સ્થિતિ આપો અને તે પાછી આવે છે.',
            'p3' => 'યાદીની ઉપર (અને ટેબલ પર) <strong>નિવૃત્ત બતાવો</strong> નિવૃત્ત એસેટ ફરી દેખાડે છે. ટેબલ <strong>નિવૃત્ત થયાની તારીખ</strong> અને <strong>કારણ</strong> કૉલમ બતાવી શકે છે અને તેમને CSV કે PDF માં એક્સપોર્ટ કરી શકે છે - ટ્રાન્સફર સાથે મોકલવાની યાદી. રિપોર્ટ પૅક્સમાંનો <strong>નિવૃત્ત એસેટ</strong> બ્લોક કોઈ સમયગાળામાં નિવૃત્ત થયેલી એસેટ બતાવે છે.',
            'p4' => 'જે નિવૃત્ત મશીન હજુ રિપોર્ટ કરે છે (ઇન્વેન્ટરી એજન્ટ, Intune) તે ઓળખાય છે - ડુપ્લિકેટ બનતું નથી - પણ તેનો રેકોર્ડ બદલાતો નથી: ફક્ત તેનું <em>છેલ્લે જોવાયું</em> ખસે છે, જેથી નેટવર્ક પર હજુ ચાલતું નિવૃત્ત મશીન દેખાય છે.',
        ],
        'review_heading' => 'જ્યારે બે રેકોર્ડ એક જ વસ્તુ હોઈ શકે',
        'review_body' => 'FreeITSM ક્યારેય અંદાજ લગાવતું નથી. જ્યારે બે એસેટનો સીરિયલ નંબર સરખો હોય, એજન્ટને નવું મશીન જૂના મશીનના નામ સાથે મળે, અથવા કોઈ ટૂલ એવું ઉપકરણ રિપોર્ટ કરે જેનો સીરિયલ કોઈ એસેટ (અથવા ઘણી) સાથે મેળ ખાતો નથી, ત્યારે તે કેસ વ્યક્તિ નિર્ણય લે તેની રાહ જોતો <strong>સેટિંગ્સ &rarr; સમીક્ષા</strong> માં રહે છે. યાદીમાંની એસેટ તેની Key info પર એ કહે છે. બે એસેટ માટે: તેમને <strong>મર્જ કરો</strong>, <strong>અલગ</strong> તરીકે ચિહ્નિત કરો (તે ખરેખર બે છે), અથવા <strong>અવગણો</strong>. અજાણ્યા ઉપકરણ માટે: તેને એસેટ તરીકે <strong>બનાવો</strong> (અને ટૂલે જ્યાં જોયું ત્યાં જોડો), અથવા અવગણો. નિર્ણયો <em>નક્કી થયેલા</em> હેઠળ ફરી ખોલી શકાય છે, અને જે કેસ પોતાની મેળે ઉકેલાઈ જાય તે આપમેળે બંધ થાય છે.',
        'merge_body' => '<strong>મર્જ બધું રાખે છે.</strong> તમે રાખવાનો રેકોર્ડ પસંદ કરો છો; બીજા પરનું બધું તેમાં જાય છે - ઇતિહાસ, ટિકિટ, કરાર, દસ્તાવેજો, પ્રોજેક્ટ્સ, લીઝ, કસ્ટડી, કનેક્શન, કસ્ટમ ફીલ્ડની કિંમતો અને ઇન્વેન્ટરી. જ્યાં બંનેમાં સરખી વસ્તુ હોય, ત્યાં તમે રાખેલી જીતે છે, અને ખાલી ફીલ્ડ બીજામાંથી ભરાય છે. પછી બીજો રેકોર્ડ દૂર થાય છે, પણ તેનું છાપેલું QR લેબલ, તેની લિંક અને REST API દ્વારા તેને રિપોર્ટ કરતા ટૂલ્સ બધા હજુ તમે રાખેલાને શોધી લે છે. મર્જ પૂર્વવત્ કરી શકાતું નથી, અને ફક્ત Discovery &amp; reconciliation પરવાનગી ધરાવનાર જ મર્જ કરી શકે છે.',
        'protect_heading' => 'ટકી રહેતા સુધારા',
        'protect_body' => 'એજન્ટ અને Intune દરેક રિપોર્ટમાં <strong>નામ</strong>, <strong>ઉત્પાદક</strong> અને <strong>મોડેલ</strong> લખે છે, જે &ldquo;Hewlett-Packard&rdquo; જેવા સુધારાને આગલા સિંકમાં પાછો ફેરવી દે. તેને સુરક્ષિત કરવા માટે એ ફીલ્ડની બાજુના <strong>તાળા</strong> પર ક્લિક કરો: કોઈ રિપોર્ટિંગ ટૂલ તેને ઓવરરાઇટ કરશે નહીં, અને જો ટૂલ કંઈક અલગ રિપોર્ટ કરે તો તે ફીલ્ડ નીચે દેખાય છે (<em>એજન્ટ &ldquo;HP&rdquo; રિપોર્ટ કરે છે</em>) અને ટૂલને ફરી જીતવા દેવા માટે <strong>છોડો</strong> છે. ટૂલ જેને રિપોર્ટ કરે તે એસેટ પર આમાંના કોઈ ફીલ્ડને સુધારવાથી તે આપમેળે સુરક્ષિત થાય છે - તેને <strong>સેટિંગ્સ &rarr; Discovery &amp; reconciliation</strong> હેઠળ બંધ કરી શકાય. સીરિયલ નંબર સુરક્ષિત કરી શકાતો નથી, કારણ કે મેચિંગ તેના પર આધાર રાખે છે. લોકો - આ પેજ પર, REST API દ્વારા કે ઇમ્પોર્ટથી - સુરક્ષિત કિંમત હજુ બદલી શકે છે.',
        'names_heading' => 'એક ઉત્પાદક, એક નામ',
        'names_body' => 'HP, HP Inc. અને Hewlett-Packard એક જ ઉત્પાદક છે, પણ ઉત્પાદક પ્રમાણેનો ચાર્ટ ત્રણ ભાગ બતાવે છે. <strong>સેટિંગ્સ &rarr; Discovery &amp; reconciliation &rarr; ઉત્પાદક અને મોડેલ નામો</strong> હેઠળ, દરેક જોડણી માટે બતાવવાનું નામ પસંદ કરો. ટેબલ દૃશ્ય, તેના ફિલ્ટર, એસેટ યાદીની શોધ અને ડેશબોર્ડ ચાર્ટ તમે પસંદ કરેલું નામ વાપરે છે; દરેક એસેટ જે રિપોર્ટ થયું તે રાખે છે (Key info તેની નીચે <em>HP તરીકે બતાવ્યું</em> કહે છે), એટલે લાઇન કાઢી નાખવાથી તે પૂર્વવત્ થાય છે. લેબલ, હેન્ડઓવર દસ્તાવેજો અને અન્ય પ્રિન્ટઆઉટ સંગ્રહિત કિંમત બતાવે છે.',
        'connected_heading' => 'શું શાની સાથે જોડાયેલું છે',
        'connected_body' => '<strong>જોડાયેલા</strong> ટૅબ એસેટ સાથે ભૌતિક રીતે શું જોડાયેલું છે તે બતાવે છે - કમ્પ્યુટર પર મોનિટર, ડોકમાં ફોન - અને તે <strong>બંને છેડેથી</strong> દેખાય છે: મોનિટર કમ્પ્યુટરને યાદીમાં બતાવે છે અને કમ્પ્યુટર મોનિટરને. જાતે નોંધવા માટે <strong>જોડો</strong> નો ઉપયોગ કરો: બીજી એસેટને નામ, સીરિયલ અથવા એસેટ ટેગથી શોધો. બંને એક જ કંપનીમાં હોવા જોઈએ. REST API દ્વારા રિપોર્ટ કરતું ટૂલ પણ તેને જે દેખાય તે નોંધી શકે છે, અને તેની લાઇન કહે છે <em>છેલ્લે lansweeper દ્વારા 3 hr પહેલાં જોડાયેલું જોવાયું</em> - તેણે તે છેલ્લે ક્યારે જોયું, હમણાં જોડાયેલું છે એમ નહીં. <strong>પુષ્ટિ કરો</strong> ટૂલની બાજુમાં તમારી પોતાની પુષ્ટિ ઉમેરે છે. દરેક જોડાણ અને ડિસ્કનેક્શન બંને એસેટના ઇતિહાસમાં છે, અને પૂરા થયેલા <strong>અગાઉના જોડાણો</strong> હેઠળ રહે છે.',
        'connected_rules' => '<strong>દરેક સ્રોત પોતાની લાઇન રાખે છે.</strong> તમે પુષ્ટિ કરેલું અને ટૂલે જોયેલું બાજુ-બાજુ રહે છે, અને કોઈ બીજાને ઓવરરાઇટ કરતું નથી: ટૂલ ક્યારેય તમારું જોડાણ પૂરું કરતું નથી, અને <strong>ડિસ્કનેક્ટ</strong> ફક્ત વ્યક્તિએ પુષ્ટિ કરેલું જોડાણ પૂરું કરે છે. રિપોર્ટ ઉલ્લેખ કરવાનું ભૂલી ગયો તેથી કશું ડિસ્કનેક્ટ થતું નથી - જે ટૂલે જોયું તે જ કહી શકે કે તે જતું રહ્યું છે. જોડાણ એ કસ્ટડી (તે કોની પાસે છે) નથી અને CMDB ડિપેન્ડન્સી નથી. મોનિટર એક કમ્પ્યુટર સાથે જોડાયેલું અને એક વ્યક્તિને સોંપાયેલું હોઈ શકે, અને એકથી બીજું બદલાતું નથી. આ ટૅબ બીજા કોઈ ટૅબની જેમ દરેક એસેટ પ્રકાર માટે છુપાવી શકાય છે.',
        'freshness_heading' => 'દરેક યાદી કેટલી તાજી છે?',
        'freshness_body' => '<strong>સ્ટોરેજ</strong>, <strong>ઉપકરણો</strong> અને <strong>સોફ્ટવેર</strong> ની ઉપર, એક લાઇન કહે છે કે કયા ટૂલે યાદી રિપોર્ટ કરી અને ક્યારે જોઈ: <em>એજન્ટ તરફથી, 3 hr પહેલાં જોયું.</em> જ્યારે તે <strong>સેટિંગ્સ &rarr; Discovery &amp; reconciliation &rarr; ઇન્વેન્ટરી આટલા પછી જૂની ગણાય</strong> (તમે ન બદલો ત્યાં સુધી 7 દિવસ) કરતાં જૂની થાય ત્યારે તે <strong>કેસરી</strong> થાય છે. જે યાદી છેલ્લા રિપોર્ટમાં રહી ગઈ તે એમ કહે છે, અને જે કલેક્શન <strong>નિષ્ફળ</strong> ગયું તે ભૂલ સાથે લાલ રંગમાં દેખાય છે - અગાઉની યાદી, તેની પોતાની ઉંમર સાથે, રાખવામાં આવે છે. Key info ના તળિયે <strong>ઇન્વેન્ટરી સ્રોતો</strong> પેનલ એસેટને રિપોર્ટ કરતા દરેક ટૂલ અને તે રાખતી દરેક યાદી બતાવે છે, અને કોઈ પ્રકારનું લેઆઉટ તેને છુપાવતું નથી. જ્યારે કોઈએ ક્યારેય યાદી રિપોર્ટ કરી નથી, ત્યારે તે એમ કહે છે અને ટૅબની ગણતરી ડેશ બતાવે છે, એટલે <strong>0</strong> નો અર્થ હંમેશા એ જ કે ટૂલે જોયું અને કંઈ મળ્યું નહીં.',
        'freshness_agent' => '<strong>ખાલી રિપોર્ટ થયું</strong> અને <strong>નિષ્ફળ</strong> 3.15.0 સાથે આવતી એજન્ટ સ્ક્રિપ્ટમાંથી આવે છે. જૂની સ્ક્રિપ્ટ &ldquo;કંઈ નહીં&rdquo; અને &ldquo;જોઈ શકી નહીં&rdquo; વચ્ચેનો ફરક કરી શકતી નથી, તેથી તેની ખાલી યાદીઓ રિપોર્ટ ન થયેલી ગણાય છે અને અગાઉની યાદી પહેલાની જેમ રાખવામાં આવે છે. તમે અપગ્રેડ કર્યું તે પહેલાં રિપોર્ટ થયેલી એસેટ તેમના આગલા રિપોર્ટ સુધી કોઈ લાઇન બતાવતી નથી.',
        'layout_heading' => 'એસેટના પ્રકારને બંધબેસતું પેજ',
        'layout_body' => 'દરેક એસેટ પ્રકાર નક્કી કરે છે કે તેની એસેટ કઈ બિલ્ટ-ઇન વિગતો અને ટૅબ બતાવે. મોનિટરને CPU, મેમરી કે ઉપકરણો ટૅબની જરૂર નથી, એટલે તેનો પ્રકાર તેમને છુપાવી શકે, અને ટૅબ તેને અનુકૂળ ક્રમમાં ગોઠવી શકાય. તેને <strong>સેટિંગ્સ &rarr; એસેટ પ્રકારો</strong> માં સેટ કરો: પ્રકાર સંપાદિત કરો અને <strong>લેઆઉટ</strong> વાપરો, અથવા શરૂઆતનો બિંદુ (પેરિફેરલ, નેટવર્ક સાધનો, મોબાઇલ ઉપકરણ) પસંદ કરો અને ટિક સમાયોજિત કરો. નામ, એસેટ ટેગ, સીરિયલ નંબર, પ્રકાર, સ્થિતિ, સ્થાન અને કંપની હંમેશા બતાવાય છે, અને Key info હંમેશા પહેલા આવે છે.',
        'layout_hidden' => '<strong>છુપાવવું ફક્ત પેજ માટે છે.</strong> કશું કાઢી નખાતું નથી, એજન્ટ અને ઇમ્પોર્ટ દરેક ફીલ્ડ નોંધતા રહે છે, અને ટેબલ દૃશ્ય અને API હજુ બધું બતાવે છે. જો એસેટમાં એવી વિગતો હોય જે તેનો પ્રકાર છુપાવે - ધારો કે કમ્પ્યુટરને ખોટો પ્રકાર અપાયો - તો Key info એમ કહે છે (<em>આ પ્રકારના લેઆઉટ દ્વારા છુપાવેલું: સોફ્ટવેર (214)</em>) અને <strong>બતાવો</strong> આપે છે, જે એ એસેટ માટે દરેક છુપાવેલું સેક્શન અને ટૅબ પાછું લાવે છે, તૂટક રૂપરેખા સાથે ચિહ્નિત. <strong>સેટિંગ્સ &rarr; એસેટ પ્રકારો &rarr; પ્રકાર છુપાવે તે વિગતો</strong> તેને બદલે શાંત <em>છુપાવેલું બતાવો</em> લિંક બનાવી શકે છે.',
        'proxmox' => [
            'nav' => 'Proxmox VE સર્વર',
            'heading' => 'Proxmox VE સર્વર',
            'intro' => 'FreeITSM એક કે વધુ Proxmox VE સર્વરમાંથી વર્ચ્યુઅલ મશીન અને LXC કન્ટેનર, નોડ, IP અને MAC સરનામાં વાંચી શકે છે અને vCenter ની બાજુમાં <strong>સર્વર</strong> હેઠળ તેમને યાદીમાં બતાવે છે. તે ફક્ત વાંચે છે: Proxmox માં ક્યારેય કશું બદલાતું નથી. સર્વર <strong>સેટિંગ્સ &rarr; Proxmox VE સર્વર</strong> હેઠળ ઉમેરો; દરેક સર્વર પોતાના શેડ્યૂલ પ્રમાણે સિંક થાય છે.',
            'user_heading' => '1. FreeITSM માટે એક વપરાશકર્તા અને ફક્ત-વાંચવાની ભૂમિકા',
            'user_1' => 'Proxmox માં, <strong>Datacenter &rarr; Permissions &rarr; Users &rarr; Add</strong>: <strong>Proxmox VE authentication server</strong> (<code>pve</code>) realm માં <code>freeitsm</code> જેવો વપરાશકર્તા. તેને પાસવર્ડની જરૂર નથી - તે ફક્ત API ટોકન ધરાવે છે.',
            'user_2' => '<strong>Datacenter &rarr; Permissions &rarr; Roles &rarr; Create</strong>: <code>FreeITSMSync</code> જેવી ભૂમિકા બનાવો, જેમાં <code>Sys.Audit</code>, <code>VM.Audit</code> અને <code>Datastore.Audit</code> હોય, ઉપરાંત ગેસ્ટના IP સરનામાં માટે Proxmox VE 9 પર <code>VM.GuestAgent.Audit</code> અથવા Proxmox VE 8 પર <code>VM.Monitor</code> (વર્ઝન 9 એ તેને બદલ્યું).',
            'user_3' => '<strong>Datacenter &rarr; Permissions &rarr; Add &rarr; User Permission</strong>: પાથ <code>/</code>, વપરાશકર્તા અને ભૂમિકા.',
            'token_heading' => '2. API ટોકન (ભલામણ કરેલ)',
            'token_1' => '<strong>Datacenter &rarr; Permissions &rarr; API Tokens &rarr; Add</strong>, તે વપરાશકર્તા માટે, <code>itsm</code> જેવા Token ID સાથે.',
            'token_2' => '<strong>Privilege Separation</strong> ની ટિક કાઢી નાખો જેથી ટોકન પાસે વપરાશકર્તાની પરવાનગીઓ હોય - અથવા તેને ટિક રહેવા દો અને પગલું 1 મુજબ ભૂમિકા ટોકનને જ આપો.',
            'token_3' => 'Proxmox <strong>સિક્રેટ</strong> ફક્ત એક જ વાર બતાવે છે. હમણાં જ તેની નકલ કરો; જો તે ખોવાઈ જાય, તો ટોકન કાઢી નાખીને બીજું બનાવો.',
            'fill_heading' => '3. FreeITSM માં સર્વર ઉમેરો',
            'fill_host' => '<strong>સર્વર સરનામું</strong>: <code>https://pve.example.com:8006</code>. ફક્ત https સ્વીકારાય છે, કારણ કે સિક્રેટ દરેક વિનંતી સાથે મોકલાય છે.',
            'fill_user' => '<strong>વપરાશકર્તા અથવા API ટોકન</strong>: ટોકન ID, <code>freeitsm@pve!itsm</code> - વપરાશકર્તા, realm, <code>!</code>, ટોકન ID. <code>freeitsm@pve</code> જેવો સામાન્ય વપરાશકર્તા પણ તેના પાસવર્ડ સાથે ચાલે છે.',
            'fill_secret' => '<strong>પાસવર્ડ</strong>: ટોકન સિક્રેટ (અથવા વપરાશકર્તાનો પાસવર્ડ). તે એન્ક્રિપ્ટ કરીને સંગ્રહાય છે અને ફરી ક્યારેય બતાવાતો નથી; સંપાદન કરતી વખતે તેને જાળવી રાખવા ખાલી છોડો.',
            'fill_verify' => '<strong>પ્રમાણપત્ર ચકાસો</strong>: વિશ્વસનીય સત્તામંડળના પ્રમાણપત્ર માટે તેને ટિક રાખો. Proxmox પોતાના સેલ્ફ-સાઇન્ડ પ્રમાણપત્ર સાથે ઇન્સ્ટોલ થાય છે; તે માટે ટિક કાઢી નાખો, અથવા વધુ સારું, Proxmox ને વિશ્વસનીય પ્રમાણપત્ર આપો.',
            'fill_interval' => '<strong>દર આટલા સમયે સિંક કરો</strong>: નિર્ધારિત સિંક વચ્ચેની મિનિટ, જે <code>cron/proxmox_sync.php</code> ચલાવે છે.',
            'test' => '<strong>ટેસ્ટ</strong> પર ક્લિક કરો, પછી <strong>હમણાં સિંક કરો</strong> અને <strong>VM બતાવો</strong>.',
            'ips_heading' => 'IP સરનામાં',
            'ips' => 'Proxmox VM નું IP સરનામું ફક્ત QEMU guest agent દ્વારા જ જાણે છે: VM ના <strong>Options</strong> માં તેને સક્ષમ કરો અને ગેસ્ટમાં <code>qemu-guest-agent</code> ઇન્સ્ટોલ કરો. ફક્ત VM ના પોતાના નેટવર્ક કાર્ડ પરના સરનામાં રાખવામાં આવે છે, તેથી તેની અંદરના Docker અને bridge ઇન્ટરફેસ છોડી દેવાય છે. કન્ટેનરનું સરનામું તેના કન્ફિગરેશનમાંથી આવે છે; DHCP વાળું જાણી શકાતું નથી.',
            'removal_heading' => 'જ્યારે VM યાદીમાંથી ગાયબ થાય',
            'removal' => 'VM ત્યારે જ દૂર થાય છે જ્યારે સફળતાપૂર્વક વાંચેલી યાદીમાં તે ન હોય. જો કોઈ નોડ ઑફલાઇન હોય, અથવા તેના VM કે કન્ટેનરની યાદી વાંચી ન શકાઈ હોય, તો તેના VM રાખવામાં આવે છે. અને જો FreeITSM જે VM ઓળખે છે તેમાંથી અડધાથી ઓછા જોવા મળ્યા, તો કશું જ દૂર થતું નથી (<strong>સલામતી રક્ષક</strong>) જ્યાં સુધી સ્વસ્થ સિંક તેની પુષ્ટિ ન કરે.',
            'trouble_heading' => 'જ્યારે કંઈક ખોટું હોય',
            'trouble_401' => '<strong>નકારાયું (HTTP 401 અથવા 403)</strong>: ટોકન ID અથવા સિક્રેટ ખોટું છે, અથવા તેની પાસે પરવાનગીઓ નથી. તપાસો કે realm <code>pve</code> છે, <code>pam</code> નહીં.',
            'trouble_reach' => '<strong>Proxmox સર્વર સુધી પહોંચી શકાયું નહીં</strong>: સરનામું અથવા પોર્ટ (સામાન્ય રીતે 8006) ખોટું છે, અથવા ફાયરવૉલ આડે આવે છે.',
            'trouble_cert' => 'Verify certificate ટિક હોય ત્યારે <strong>પ્રમાણપત્રની ભૂલ</strong>: Proxmox પોતાનું સેલ્ફ-સાઇન્ડ પ્રમાણપત્ર વાપરે છે. ટિક કાઢી નાખો, અથવા Proxmox પર વિશ્વસનીય પ્રમાણપત્ર ઇન્સ્ટોલ કરો.',
            'trouble_node' => '<strong>આ ચક્રમાં પહોંચી શકાયું નહીં: નોડનું નામ</strong>: તે નોડ અથવા તેની યાદીએ જવાબ આપ્યો નહીં. તેના VM રાખવામાં આવે છે.',
            'trouble_guard' => '<strong>સલામતી રક્ષક</strong>: જાણીતા VM માંથી અડધાથી ઓછા જોવા મળ્યા અને કશું કાઢી નખાયું નથી. સામાન્ય રીતે પરવાનગી અથવા ઑફલાઇન નોડનો પ્રશ્ન હોય છે, વાસ્તવિક કાઢી નાખવાનો નહીં.',
            'more' => 'સંપૂર્ણ માર્ગદર્શિકા wiki પર છે: <a href="https://github.com/edmozley/freeitsm/wiki/Proxmox-VE" target="_blank" rel="noopener">Proxmox VE</a>.',
        ],
        'vcloud' => [
            'nav' => 'Cloud Director સર્વર',
            'heading' => 'VMware Cloud Director સર્વર',
            'intro' => 'FreeITSM એક કે વધુ VMware Cloud Director સર્વરમાંથી VM, તેમના નેટવર્ક કાર્ડ અને ડિસ્ક સાથે, અને edge gateway વાંચી શકે છે અને VM ને <strong>સર્વર</strong> હેઠળ યાદીમાં બતાવે છે. તે ફક્ત વાંચે છે. સર્વર <strong>સેટિંગ્સ &rarr; VMware Cloud Director સર્વર</strong> હેઠળ ઉમેરો.',
            'user_heading' => '1. વપરાશકર્તા પસંદ કરો',
            'user_1' => 'એક organization માટે: તેમાંનો <strong>Organization Administrator</strong> ભૂમિકા ધરાવતો વપરાશકર્તા, અથવા તેના VM અને નેટવર્ક જોઈ શકે તેવી ફક્ત-વાંચવાની ભૂમિકા.',
            'user_2' => 'દરેક organization માટે: organization <code>System</code> સાથે provider administrator.',
            'fill_heading' => '2. FreeITSM માં સર્વર ઉમેરો',
            'fill_host' => '<strong>સર્વર સરનામું</strong>: <code>https://vcd.example.com</code>, Cloud Director પોર્ટલનું સરનામું. ફક્ત https સ્વીકારાય છે.',
            'fill_org' => '<strong>Organization</strong>: તેનું <em>નામ</em> - સાઇન ઇન કરતી વખતે સરનામામાં હોય તે (<code>/tenant/acme</code> એટલે <code>acme</code>) - તેનું પ્રદર્શન નામ નહીં. provider administrator માટે <code>System</code>.',
            'fill_user' => '<strong>વપરાશકર્તા</strong> અને <strong>પાસવર્ડ</strong>: પગલું 1 નો વપરાશકર્તા, <code>@organization</code> વગર. પાસવર્ડ એન્ક્રિપ્ટ કરીને સંગ્રહાય છે અને ફરી ક્યારેય બતાવાતો નથી.',
            'fill_version' => '<strong>API વર્ઝન</strong>: Cloud Director 10.5 માટે <code>38.0</code>, 10.3 માટે <code>36.2</code>. સર્વર જે વર્ઝન ન આપતું હોય તે ટેસ્ટ વખતે સ્પષ્ટ રીતે નિષ્ફળ થાય છે.',
            'fill_verify' => '<strong>પ્રમાણપત્ર ચકાસો</strong>: પોર્ટલ સેલ્ફ-સાઇન્ડ પ્રમાણપત્ર વાપરતું ન હોય ત્યાં સુધી તેને ટિક રાખો.',
            'test' => '<strong>ટેસ્ટ</strong> પર ક્લિક કરો, પછી <strong>હમણાં સિંક કરો</strong> અને <strong>VM બતાવો</strong>, જે edge gateway ની યાદી પણ બતાવે છે.',
            'removal_heading' => 'જ્યારે VM યાદીમાંથી ગાયબ થાય',
            'removal' => 'ફક્ત આખી VM યાદી, તેના દરેક પેજ સાથે, વાંચ્યા પછી જ. જો કોઈ પેજ નિષ્ફળ જાય, તો તે વખતે કશું દૂર થતું નથી. એ જ સલામતી રક્ષક લાગુ પડે છે: જાણીતા VM માંથી અડધાથી ઓછા જોવા મળે તો કશું દૂર થતું નથી. Edge gateway પણ તેમના બધા પેજ વંચાયા પછી જ દૂર થાય છે.',
            'trouble_heading' => 'જ્યારે કંઈક ખોટું હોય',
            'trouble_401' => '<strong>લોગિન નકારાયું (HTTP 401 અથવા 403)</strong>: વપરાશકર્તા, પાસવર્ડ અથવા organization ખોટું છે - સામાન્ય રીતે organization ના નામને બદલે તેનું પ્રદર્શન નામ લખાયું હોય છે.',
            'trouble_reach' => '<strong>vCloud Director સર્વર સુધી પહોંચી શકાયું નહીં</strong>: સરનામું ખોટું છે, અથવા ફાયરવૉલ આડે આવે છે.',
            'trouble_partial' => '<strong>ફક્ત આંશિક રીતે વાંચી શકાયું</strong>: VM યાદીનું એક પેજ નિષ્ફળ ગયું. કશું દૂર થયું નથી; આગામી સિંક ફરી પ્રયાસ કરશે.',
            'trouble_guard' => '<strong>સલામતી રક્ષક</strong>: જાણીતા VM માંથી અડધાથી ઓછા જોવા મળ્યા અને કશું કાઢી નખાયું નથી. સામાન્ય રીતે વપરાશકર્તાએ અધિકારો ગુમાવ્યા હોય, અથવા organization બદલાયું હોય.',
            'more' => 'સંપૂર્ણ માર્ગદર્શિકા wiki પર છે: <a href="https://github.com/edmozley/freeitsm/wiki/VMware-Cloud-Director" target="_blank" rel="noopener">VMware Cloud Director</a>.',
        ],
        'companies' => [
            'nav' => 'એસેટ્સ અને કંપનીઓ',
            'heading' => 'એસેટ્સ અને કંપનીઓ',
            'intro' => 'એક કરતાં વધુ કંપનીની સંભાળ રાખતા ઇન્સ્ટોલેશન પર, દરેક એસેટ તેમાંથી કોઈ એકની હોય છે. <em>જો તમે FreeITSM એક જ કંપની માટે ચલાવતા હો તો આ વિભાગ લાગુ પડતો નથી.</em>',
            'move' => '<strong>એસેટ ખસેડવી</strong> &mdash; <strong>Key info</strong> પર, એસેટ ટેગની બાજુમાં <strong>કંપની</strong> ફીલ્ડ બદલો અને પુષ્ટિ કરો. તમે ફક્ત એવી કંપનીમાં એસેટ ખસેડી શકો છો જે તમે પોતે ઍક્સેસ કરી શકો, અને ખસેડવાની નોંધ તેના ઇતિહાસમાં થાય છે.',
            'cleared' => '<strong>શું સાફ થાય છે</strong> &mdash; જે ફક્ત જૂની કંપનીનું હોય તે બધું: તેનું સ્થાન (સિવાય કે સ્થાન શેર્ડ હોય), અને જૂની કંપનીએ પોતાના માટે ઉમેરેલો પ્રકાર કે સ્થિતિ. ખસેડ્યા પછીનો સંદેશ જણાવે છે કે શું સાફ થયું. ઇતિહાસ, કસ્ટમ ફીલ્ડ્સ, દસ્તાવેજો અને તેને ધરાવતો વિશ્લેષક બધું સાથે ખસે છે.',
            'refused' => '<strong>જ્યારે ખસેડવાનું નકારાય</strong> &mdash; જ્યારે નવી કંપની પાસે સમાન નામ અથવા એસેટ ટેગ વાળી એસેટ પહેલેથી હોય, અથવા જ્યારે એસેટ બીજી કંપનીની વ્યક્તિ પાસે હોય. સંદેશ જણાવે છે કે કયું, જેથી તમે તે સુધારીને ફરી પ્રયાસ કરી શકો.',
            'add' => '<strong>એસેટ ઉમેરવી</strong> &mdash; જ્યારે તમે એક કરતાં વધુ કંપની ઍક્સેસ કરી શકો, ત્યારે <strong>એસેટ ઉમેરો</strong> પૂછે છે કે તે કઈ માટે છે, અને પ્રકાર, સ્થિતિ અને સ્થાનની યાદીઓ તમારી પસંદગીને અનુસરે છે. <strong>બધી કંપનીઓ</strong> દૃશ્યમાં કોઈ ડિફોલ્ટ નથી, તેથી નવી એસેટ તમે છેલ્લે પસંદ કરેલી કંપનીમાં આપોઆપ ઉમેરાઈ શકતી નથી.',
            'shared' => '<strong>શેર્ડ સ્થાનો</strong> &mdash; <strong>સેટિંગ્સ &rarr; સ્થાનો</strong> હેઠળ, દરેક કંપનીની ઍક્સેસ ધરાવતી વ્યક્તિ કોઈ સ્થાનને <strong>દરેક કંપની સાથે શેર્ડ</strong> તરીકે ચિહ્નિત કરી શકે છે, જેમ કે ઘણા ક્લાયન્ટ વાપરતા હોય તેવું ડેટા સેન્ટર. પછી દરેક કંપની પોતાના સ્થાનોની સાથે તેને પસંદ કરી શકે છે. જ્યાં સુધી બીજી કંપનીઓની એસેટ્સ હજુ ત્યાં હોય ત્યાં સુધી શેર્ડ સ્થાનને અનશેર કરી શકાતું નથી.',
            'note' => 'એસેટ યાદી હજુ પણ એક સમયે એક કંપની બતાવે છે, <strong>બધી કંપનીઓ</strong> દૃશ્યમાં પણ. ખસેડાયેલી એસેટ તમે જોઈ રહ્યા છો તે યાદીમાંથી જતી રહે છે &mdash; તેને જોવા માટે તેની નવી કંપની પર સ્વિચ કરો.',
            'recon' => '<strong>હાર્ડવેર ડિસ્કવરી અને રિકન્સિલિએશન</strong> &mdash; સ્વયંસંચાલિત ઇન્વેન્ટરી રિપોર્ટ (PowerShell એજન્ટ અથવા Microsoft Intune તરફથી) એસેટ્સને ફક્ત લક્ષ્ય કંપનીની અંદર જ મેળવે છે. જુદી જુદી કંપનીઓમાં સમાન સીરિયલ નંબર અથવા હોસ્ટનામ સંપૂર્ણપણે અલગ રહે છે અને ક્યારેય સીમા ઓળંગતા નથી.',
        ],
        'asset_tags' => [
            'nav' => 'આપોઆપ એસેટ ટેગ',
            'heading' => 'આપોઆપ એસેટ ટેગ',
            'intro' => '<strong>સેટિંગ્સ &rarr; એસેટ ટેગ</strong> ચાલુ કરો અને દરેક નવી એસેટને ક્રમમાં આગળનો ટેગ મળશે - પછી ભલે તે હાથથી ઉમેરાઈ હોય, REST API દ્વારા, સ્પ્રેડશીટ ઇમ્પોર્ટથી, ઇન્વેન્ટરી એજન્ટ દ્વારા કે Intune દ્વારા. હાથથી લખેલો ટેગ હંમેશા રાખવામાં આવે છે. તમે ચાલુ ન કરો ત્યાં સુધી બંધ.',
            'monotonic_strong' => 'ફોર્મેટ',
            'monotonic_text' => 'એક લાઇન, ટિકિટ નંબરિંગ જેવા જ ટોકન: <code>AST-{#####}</code>, <code>{COMPANY}-LT-{####}</code>, <code>IT{YY}-{######}</code>. # ની સંખ્યા ઓછામાં ઓછા અંકો છે, ક્યારેય મર્યાદા નહીં. જ્યાં સુધી તમે બધામાં એક જ વાર ગણવાનું પસંદ ન કરો ત્યાં સુધી દરેક કંપની પોતાની રીતે ગણે છે.',
            'lifecycle_strong' => 'નંબર ક્યારેય ફરી વપરાતા નથી',
            'lifecycle_text' => 'ટેગ સ્ટિકર, ઇન્વૉઇસ અને સ્પ્રેડશીટમાં પહોંચી જાય છે, તેથી એક વાર આપેલો નંબર ફરી ક્યારેય અપાતો નથી - એસેટ કાઢી નાખ્યા પછી પણ નહીં, અને કાઉન્ટર ખસેડો તો પણ નહીં. તમે તેને આગળ ખસેડી શકો, પાછળ ક્યારેય નહીં. ટેગ એસેટ પર જ બદલી શકાય છે, અને ફેરફાર તેના ઇતિહાસમાં હોય છે; QR કોડ કામ કરતો રહે છે, કારણ કે તેમાં ક્યારેય ટેગ હતો જ નહીં.',
        ],
        'asset_labels' => [
            'nav' => 'ભૌતિક એસેટ લેબલ &amp; QR કસ્ટમાઇઝેશન',
            'heading' => 'ભૌતિક એસેટ લેબલ અને QR કસ્ટમાઇઝેશન',
            'intro' => 'A4 શીટ પર અથવા લેબલ પ્રિન્ટરની ટેપ કે રોલ પર, લેબલના ચોક્કસ કદના PDF તરીકે એસેટ લેબલ પ્રિન્ટ કરો - અથવા વ્યાવસાયિક પ્રિન્ટ હાઉસ માટે એસેટ ડેટા એક્સપોર્ટ કરો.',
            'fields_strong' => 'ગોઠવી શકાય તેવી ફીલ્ડ પસંદગી',
            'fields_text' => '<strong>સેટિંગ્સ &rarr; એસેટ લેબલ &amp; QR</strong> હેઠળ, કયા ફીલ્ડ અને કયા ક્રમમાં દેખાય તે પસંદ કરો - હોસ્ટનામ, સીરિયલ, મોડેલ, સ્થાન, ફાયનાન્સ ID જેવા તમારા પોતાના કસ્ટમ ફીલ્ડ્સ - ઉપરાંત હેડર, ફૂટર અને દરેક ફીલ્ડનું નામ પ્રિન્ટ કરવું કે નહીં. એસેટ ટેગ હંમેશા લેબલ પર હોય છે.',
            'qr_strong' => 'QR કોડ અને લોગો',
            'qr_text' => 'QR કોડ ઇન્સ્ટોલેશનના જાહેર સરનામાનો ઉપયોગ કરીને FreeITSM માં એસેટ ખોલે છે. તમે તેની વચ્ચે તમારો લોગો મૂકી શકો છો; ત્યારે કોડ વધુ બિલ્ટ-ઇન રિડન્ડન્સી સાથે પ્રિન્ટ થાય છે જેથી તે હજુ સ્કેન થઈ શકે. આખો બેચ પ્રિન્ટ કરતાં પહેલાં એક સૌથી નાના કદમાં પ્રિન્ટ કરો અને સામાન્ય ફોનથી સ્કેન કરી જુઓ.',
            'designs_strong' => 'લેબલ ડિઝાઇન',
            'designs_text' => '<strong>સેટિંગ્સ &rarr; એસેટ લેબલ અને QR &rarr; લેબલ ડિઝાઇન</strong> હેઠળ, ઘણી ડિઝાઇન રાખો - દરેક લેબલ કદ પર એક લેઆઉટ - અને <strong>લેબલ પ્રિન્ટ કરો</strong> જે વાપરે તે પસંદ કરો. લેઆઉટ: <em>સ્ટાન્ડર્ડ</em> (લેબલ હંમેશા જેવું દેખાતું હતું), <em>લોગો ડાબે, વિગતો વચ્ચે, QR જમણે</em> (તમારો લોગો મોટો, ટેપ લેબલ માટે), <em>નાનું</em> (QR અને ટેગ) અને <em>મોટું</em> (લોગો, QR, પછી વિગતો). તે ટૅબમાં નીચે સેટ કરેલા હેડર, ફૂટર, ફીલ્ડ અને લોગો વાપરે છે. પ્રિન્ટ પેજ પર તમે એક પ્રિન્ટ માટે બીજી ડિઝાઇન કે કદ પસંદ કરી શકો છો.',
            'designer_strong' => 'લેબલ ડિઝાઇનર',
            'designer_text' => 'સ્લાઇડની જેમ લેબલ જાતે ગોઠવવા માટે ડિઝાઇનની બાજુમાં <strong>ડિઝાઇન</strong> દબાવો: ટૂલબોક્સમાંથી ટેક્સ્ટ, ફીલ્ડ, ફીલ્ડ યાદી, QR કોડ, તમારો લોગો, લાઇન અને બોક્સ ખેંચો, પછી તેમને ખસેડો અને માપ બદલો - તે લેબલની કિનારીઓ અને મધ્યમાં અને એકબીજા સાથે સ્નેપ થાય છે. લેબલ ખરી એસેટની કિંમતો બતાવે છે, અને <em>લાંબી કિંમતો સાથેનો નમૂનો</em> સૌથી ખરાબ કિસ્સો બતાવે છે; દરેક ટેક્સ્ટ નક્કી કરે છે કે લાંબી કિંમત નાની થાય, વીંટાય કે કપાય. ગોઠવો વસ્તુઓને લાઇનમાં લાવે છે, એરો કી સહેજ ખસેડે છે, અને Ctrl+Z પૂર્વવત્ કરે છે. ડિઝાઇનરમાં સાચવ્યા પછી, ડિઝાઇન તમે ગોઠવ્યું તે જ રાખે છે અને ટૅબમાં નીચે સેટ કરેલા હેડર, ફૂટર અને ફીલ્ડને હવે અનુસરતી નથી.',
            'sizes_strong' => 'લેબલ કદ અને પ્રિન્ટિંગ',
            'sizes_text' => 'Brother TZe અને DK ટેપ, Dymo લેબલ, ચાર A4 શીટ, અથવા તમારું પોતાનું કદ. <strong>ડાઉનલોડ</strong> લેબલના ચોક્કસ કદનું PDF બનાવે છે - ટેપ કે રોલ પ્રિન્ટર માટે પેજ દીઠ એક લેબલ. તેને પ્રિન્ટરના પોતાના ડ્રાઇવર દ્વારા <strong>વાસ્તવિક કદ</strong> માં પ્રિન્ટ કરો ("Fit to page" ક્યારેય નહીં). શીટ માટે, જો તમારા લેબલ થોડા ખસેલા પ્રિન્ટ થાય તો 10 mm સુધીનો પ્રિન્ટર ઓફસેટ દરેક લેબલને ખસેડે છે. ટેપ કે રોલ પ્રિન્ટર માટેની ડિઝાઇન ઘટ્ટ કાળા રંગમાં પ્રિન્ટ થાય છે - ટેક્સ્ટ, લાઇન અને કાળો-સફેદ લોગો - કારણ કે તે પ્રિન્ટર ગ્રે રંગને ટપકાં તરીકે છાપે છે જે વાંચવા મુશ્કેલ છે. રંગીન લેબલ માટે ડિઝાઇન પર <strong>ફક્ત-કાળું પ્રિન્ટર</strong> અનટિક કરો.',
            'fonts_strong' => 'ફોન્ટ અને અન્ય ભાષાઓ',
            'fonts_text' => 'લેબલ Noto Sans વાપરે છે, અને તેમાં ન હોય તે કોઈપણ અક્ષર કમ્પ્યુટરના પોતાના ફોન્ટથી દોરાય છે, એટલે કોઈપણ ભાષાના નામ પ્રિન્ટ થાય છે. <strong>લેબલ ફોન્ટ</strong> હેઠળ ફોન્ટ અપલોડ કરો - તમારો બ્રાન્ડ ફોન્ટ, અથવા ભાષા માટેનો - અને તેને ડિઝાઇન પર પસંદ કરો. ડિઝાઇન જે ફોન્ટ વાપરે છે તે કાઢી શકાતો નથી.',
        ],
        'reconciliation' => [
            'nav' => 'ડિસ્કવરી &amp; રિકન્સિલિએશન',
            'heading' => 'ડિસ્કવરી અને રિકન્સિલિએશન',
            'intro' => 'જ્યારે કોઈ કમ્પ્યુટર રિપોર્ટ કરે - ઇન્વેન્ટરી એજન્ટ અથવા Microsoft Intune તરફથી - ત્યારે FreeITSM પહેલાં તેના સીરિયલ નંબરથી અને પછી તેના નામથી નક્કી કરે છે કે તે કઈ એસેટ છે, તેથી નામ બદલેલું કમ્પ્યુટર પણ એ જ એસેટ રહે છે.',
            'renames_strong' => 'નામ બદલેલું કમ્પ્યુટર',
            'renames_text' => 'તેનો સીરિયલ નંબર હાલની એસેટ શોધે છે, જે નવું નામ લે છે - ફેરફાર તેના ઇતિહાસમાં હોય છે - અને તેનો ધારક, ટિકિટ, કરાર અને સોફ્ટવેર જાળવી રાખે છે. પહેલાં, નામ બદલવું બીજી એસેટ તરીકે આવતું હતું.',
            'ignored_strong' => 'અર્થહીન સીરિયલ નંબર',
            'ignored_text' => 'કેટલાક મશીન <em>To be filled by O.E.M.</em> જેવો પ્લેસહોલ્ડર રિપોર્ટ કરે છે. તે અવગણાય છે અને તેના બદલે નામ વપરાય છે. યાદી <strong>સેટિંગ્સ &rarr; ડિસ્કવરી &amp; રિકન્સિલિએશન</strong> હેઠળ છે. જો બે એસેટ્સ સમાન વાસ્તવિક સીરિયલ વહેંચે, તો FreeITSM તેમની વચ્ચે અંદાજ લગાવતું નથી.',
            'refresh_strong' => 'જૂના નામ સાથેનું રિપ્લેસમેન્ટ',
            'refresh_text' => 'નવા લેપટોપને ઘણીવાર જૂનાનું નામ અપાય છે. તેનો સીરિયલ અલગ હોવાથી, તે જૂનો રેકોર્ડ સંભાળવાને બદલે નવી એસેટ બની જાય છે - અને તેના ઇતિહાસમાં નોંધ હોય છે કે કઈ એસેટ પાસે હજુ તે નામ છે, જેથી તમે જૂનીનું નામ બદલી શકો અથવા તેને નિવૃત્ત કરી શકો.',
            'intune_strong' => 'Intune',
            'intune_text' => 'Intune એ એસેટ સાથે જોડેલું ઉપકરણ જોડાયેલું જ રહે છે, તમે એસેટને બીજી કંપનીમાં ખસેડો ત્યારે પણ. નવી એસેટ બનાવતા પહેલાં નવા ઉપકરણો સીરિયલ, પછી નામથી મેળવાય છે. <strong>સિસ્ટમ &rarr; ઇન્ટિગ્રેશન્સ &rarr; Microsoft 365 &rarr; Intune</strong> પસંદ કરે છે કે નવા ઉપકરણો કઈ કંપનીમાં મેળવાય અને બને, અને Intune માં ઉપકરણનું નામ બદલાય ત્યારે એસેટનું નામ બદલાય કે નહીં - અપગ્રેડ પછી બંધ, એટલે તમે પસંદ ન કરો ત્યાં સુધી કશાનું નામ બદલાતું નથી.',
            'intune_holder_strong' => 'Intune તરફથી ધારકો',
            'intune_holder_text' => 'લોકોને Microsoft Entra ID માંથી ઇમ્પોર્ટ કર્યા પછી, <strong>સિસ્ટમ &rarr; ઇન્ટિગ્રેશન્સ &rarr; Microsoft 365 &rarr; Intune</strong> જે એસેટ કોઈ પાસે નથી તેને તેના ઉપકરણના પ્રાથમિક વપરાશકર્તાને પણ સોંપી શકે છે, Entra ઑબ્જેક્ટ id થી ચોક્કસ મેળવીને. જેના ધારક પહેલેથી હોય તે એસેટ ક્યારેય બદલાતી નથી, અને તમે ચાલુ ન કરો ત્યાં સુધી તે બંધ છે.',
            'intune_holder_when' => 'તે દરેક Intune સિંક અને દરેક Entra ઇમ્પોર્ટ પછી ચાલે છે, એટલે બેમાંથી કયું પહેલા ચાલે તેનાથી ફરક પડતો નથી.',
            'companies_strong' => 'એકથી વધુ કંપનીઓ',
            'companies_text' => 'ઇન્વેન્ટરી એજન્ટ ફક્ત તેની કીની કંપનીની અંદર જ મેળવે છે, તેથી સમાન કમ્પ્યુટર નામ અથવા સીરિયલ ધરાવતી બે કંપનીઓ ક્યારેય ગૂંચવાતી નથી.',
        ],
        'page_title' => 'એસેટ વ્યવસ્થાપન માર્ગદર્શિકા',
