        'hero_subtitle' => 'તમારા એસ્ટેટમાંના દરેક ઉપકરણને શોધો, ટ્રૅક કરો અને વ્યવસ્થાપિત કરો &mdash; લેપટોપથી લઈને સર્વર્સ સુધી.',
        'cf_page_title' => 'કંઈપણ નોંધવું',
        'cf_guide' => 'માર્ગદર્શિકા',
        'cf_hero_title' => 'કંઈપણ નોંધવું, અને તેને ઇમ્પોર્ટ કરવું',
        'cf_hero_subtitle' => 'પ્રિન્ટર, મોનિટર, હેડસેટ, ટેલિવિઝન &mdash; તમારે જે પણ ટ્રૅક કરવાની જરૂર હોય, તમને જે વિગતો મહત્વની લાગે તેની સાથે.',
        'cf_nav_why' => 'આ કેમ છે',
        'cf_nav_idea' => 'ફીલ્ડ્સ, સેટ્સ અને પ્રકારો',
