        'cf_nav_attention' => 'ધ્યાન માંગતી પંક્તિઓ',
        'cf_nav_using' => 'કિંમતો ક્યાં દેખાય છે',
        'cf_nav_gotchas' => 'જાણવા જેવી બાબતો',
        'cf_link' => 'કંઈપણ નોંધવું (પ્રિન્ટર, TV, હેડસેટ) &amp; ઇમ્પોર્ટ કરવું',
        'overview_cf_lead' => 'કમ્પ્યુટર ન હોય તેવી વસ્તુ ટ્રૅક કરી રહ્યા છો?',
        'overview_cf_body' => 'પ્રિન્ટર, મોનિટર, હેડસેટ અને ટેલિવિઝન ઇન્વેન્ટરી સ્ક્રિપ્ટ ચલાવતા નથી અને નીચેની કોઈ વિગતો ધરાવતા નથી. તમે તેમને હાથે ઉમેરી શકો છો અથવા સ્પ્રેડશીટ ઇમ્પોર્ટ કરી શકો છો, અને દરેક પ્રકારની એસેટ સામે તમને જે વિગતો મહત્વની લાગે તે નોંધી શકો છો &mdash; આ બધા માટે એક અલગ માર્ગદર્શિકા છે.',
        'nav_overview' => 'ઝાંખી',
        'nav_asset_detail' => 'એસેટ વિગત દૃશ્ય',
        'nav_table_view' => 'ટેબલ દૃશ્ય',
        'nav_inventory_script' => 'ઇન્વેન્ટરી સ્ક્રિપ્ટ',
        'nav_what_collected' => 'શું એકત્રિત થાય છે',
        'nav_deployment' => 'મોટા પાયે ડિપ્લોય કરવું',
        'nav_servers' => 'સર્વર્સ અને vCenter',
        'nav_dashboard' => 'ડેશબોર્ડ',
        'nav_users' => 'કોની પાસે શું છે',
        'nav_tips' => 'ઝડપી ટિપ્સ',
        'users_heading' => 'કોની પાસે શું છે',
        'users_intro' => '<strong>Users</strong> ટૅબ એવા પ્રશ્નનો જવાબ આપે છે જેના માટે પહેલા એસેટ યાદીમાં એક-એક વસ્તુ શોધવી પડતી હતી: આ વ્યક્તિ પાસે ખરેખર શું છે? કોઈને પસંદ કરો અને તમે તેમને સોંપાયેલ બધું એક જ સ્ક્રીન પર જુઓ, અને તેમને સહી કરવા માટે હેન્ડઓવર દસ્તાવેજ પ્રિન્ટ કરી શકો છો.',
        'users_step1_strong' => 'વ્યક્તિ શોધો.',
        'users_step1_list' => 'ડાબી બાજુની યાદીમાં તમારા હાલના લોકો બતાવવામાં આવે છે, દરેક પાસે શું છે તેની ગણતરી સાથે. નામ, ઈમેલ અથવા વિભાગ દ્વારા શોધો, અને પહેલા ડ્રોપડાઉનનો ઉપયોગ <strong>છોડી ગયેલા</strong>, <strong>બધા</strong> અથવા ફક્ત <strong>ઉપકરણ ધરાવતા</strong> લોકો માટે કરો. જ્યારે લોકો ડિરેક્ટરી અથવા એડ્રેસ બુકમાંથી આવે છે, ત્યારે બીજું ડ્રોપડાઉન, <strong>સ્રોત</strong>, ફક્ત તેમાંથી એકના લોકોને, અથવા ફક્ત FreeITSMમાં ઉમેરાયેલા લોકોને યાદીમાં બતાવે છે; તેમની વિગતો જણાવે છે કે તેઓ ક્યાંથી આવે છે. જે કોઈ કોઈપણ એડ્રેસ બુકમાં નથી તેને <strong>એડ્રેસ બુકમાં ઉમેરો</strong> વડે એકમાં ઉમેરી શકાય છે, જો કોઈ એડમિનિસ્ટ્રેટરે તે એડ્રેસ બુક માટે તેની મંજૂરી આપી હોય.',
        'users_step2_strong' => 'તેઓ શું ધરાવે છે તે જુઓ.',
        'users_step2_text' => 'વ્યક્તિ પર ક્લિક કરવાથી તેમને સોંપાયેલ દરેક વસ્તુ તેના પ્રકાર, નામ, બ્રાન્ડ અને મોડેલ, સીરિયલ નંબર, એસેટ ટેગ અને સોંપણીની તારીખ સાથે બતાવાય છે &mdash; જે ઓડિટ અથવા ઑફબોર્ડિંગ તપાસ માટે ખરેખર જરૂરી છે.',
        'users_step3_strong' => 'હેન્ડઓવર દસ્તાવેજ પ્રિન્ટ કરો અથવા ઇમેઇલ કરો.',
        'users_step3_text' => '<strong>Handover document</strong> બટન વ્યક્તિ, તેમની સાધનસામગ્રી અને સોંપણીની તારીખો દર્શાવતો રેકોર્ડ બનાવે છે, ઘોષણા સાથે અને તેમના તથા IT બંને માટે સહી કરવાની જગ્યા સાથે. તેને પ્રિન્ટ કરો, ઇલેક્ટ્રોનિક નકલ માટે તમારા બ્રાઉઝરનું <strong>Save as PDF</strong> વાપરો, અથવા વ્યક્તિને સીધું મોકલવા માટે <strong>Email to them</strong> વાપરો. જો તમે <strong>System &rarr; Branding</strong> હેઠળ કંપની લોગો સેટ કર્યો હોય તો તે તેના પર દેખાય છે.',
        'users_step4_strong' => 'દસ્તાવેજ શું કહે છે તે બદલો.',
        'users_step4_text' => '<strong>Settings &rarr; Handover document</strong> તમને તેની ગોઠવણી કરવા દે છે: વિભાગો ચાલુ કે બંધ કરો, તેમનો ક્રમ બદલો, ફરીથી શબ્દરચના કરો, અને સાધનસામગ્રી ટેબલ કઈ કૉલમ બતાવે તે પસંદ કરો &mdash; તમારા પોતાના કસ્ટમ ફીલ્ડ્સ સહિત, જેથી મોનિટર માટે તેની સાઇઝ અને રિઝોલ્યુશન સાથે કાગળ પર સહી થાય. કસ્ટમ કૉલમ તમે ચાલુ ન કરો ત્યાં સુધી બંધ રહે છે, કારણ કે હેન્ડઓવર એ કોઈ સહી કરે તેવો રેકોર્ડ છે. <code>{{employee.name}}</code> જેવા મર્જ કોડ્સ દસ્તાવેજ બનતી વખતે પોતાની મેળે ભરાય છે, અને લાઇવ પ્રીવ્યૂ તમે ટાઇપ કરો તેમ પરિણામ બતાવે છે.',
        'users_step5_strong' => 'તેમની વિગતો અપ ટુ ડેટ રાખો.',
        'users_step5_text' => '<strong>સંપાદિત કરો</strong> વ્યક્તિ એડિટર ખોલે છે &mdash; એ જ જે Tickets &rarr; Users ખોલે છે, તેથી નામ, સંપર્ક વિગતો, કંપની, મેનેજર અને પાસવર્ડ તમે ક્યાંય પણ હો ત્યાં એ જ રીતે બદલાય છે. મેનેજર માટે, તેમને શોધવા નામનો થોડો ભાગ લખો. <strong>છોડી ગયા તરીકે ચિહ્નિત કરો</strong> વ્યક્તિ અને તેમણે ધારણ કરેલું બધું રેકોર્ડ પર રાખે છે અને તેમને વર્તમાન યાદીમાંથી કાઢે છે; <strong>ફરી સક્રિય કરો</strong> તેમને પાછા લાવે છે. જ્યાં વ્યક્તિ ડિરેક્ટરી અથવા એડ્રેસ બુકમાંથી આવે છે, ત્યાં તેની માલિકીની વિગતો ગ્રે કરેલી હોય છે.',
        'users_managers' => '<strong>મેનેજર.</strong> જ્યાં કોઈ વ્યક્તિ લોકોને મેનેજ કરે છે, ત્યાં તેમની વિગતો તેમને કોણ રિપોર્ટ કરે છે તે યાદી આપે છે. <strong>મેનેજર ઍક્સેસ</strong> પૂર્ણ-સ્ક્રીન પેજ ખોલે છે જે સેલ્ફ-સર્વિસ પોર્ટલમાં તે વ્યક્તિ કોની ટિકિટ જોઈ શકે છે તે દર્શાવે છે, અને તમને તેમની ટીમમાં લોકો, જૂથો અથવા વિભાગો ઉમેરવા કે બાકાત રાખવા દે છે; તેઓ જેને જોઈ શકે છે તેમાંથી કોઈપણ પર ક્લિક કરો તો કારણ જાણી શકાય. તેની અસર ત્યારે જ થાય છે જ્યારે વ્યવસ્થાપક <strong>System &rarr; Managers</strong> હેઠળ મેનેજર ચાલુ કરે.',
        'users_tip' => 'સાધનસામગ્રી એસેટ પર જ વ્યક્તિને સોંપાયેલ છે, તેથી જો કોઈ આ યાદીમાંથી ખૂટે અથવા કોઈ વસ્તુ ખોટી લાગે, તો એસેટ ખોલો અને તેનો સોંપાયેલ વપરાશકર્તા તપાસો.',
        'overview_intro' => 'એસેટ વ્યવસ્થાપન તમને તમારા IT એસ્ટેટની સંપૂર્ણ ઇન્વેન્ટરી આપે છે. Windows મશીનો PowerShell સ્ક્રિપ્ટનો ઉપયોગ કરીને આપમેળે રિપોર્ટ કરે છે, અને VMware વર્ચ્યુઅલ મશીનો vCenter માંથી સિંક થાય છે. બધું એક જગ્યાએ આવે છે જ્યાં તમે શોધી શકો, વપરાશકર્તાઓ સોંપી શકો અને ડેશબોર્ડ બનાવી શકો.',
        'card_assets_title' => 'એસેટ્સ',
        'card_assets_desc' => 'દરેક શોધાયેલ મશીન બ્રાઉઝ કરો અને શોધો. તેના હાર્ડવેર, સ્ટોરેજ, ઉપકરણો અને ઇન્સ્ટોલ કરેલ સોફ્ટવેરને એક નજરમાં જોવા માટે કોઈપણ એસેટ પર ક્લિક કરો.',
        'card_dashboard_title' => 'ડેશબોર્ડ',
        'card_dashboard_desc' => '13+ ચાર્ટ પ્રકારોમાંથી તમારું પોતાનું ડેશબોર્ડ બનાવો &mdash; OS વિતરણ, ઉત્પાદક વિભાજન, મેમરી સ્તરો અને વધુ. દરેક વિશ્લેષક પાસે પોતાનું લેઆઉટ હોય છે.',
        'card_servers_title' => 'સર્વર્સ',
        'card_servers_desc' => 'VMware vCenter સાથે કનેક્ટ કરો અને તમારા સમગ્ર વર્ચ્યુઅલ એસ્ટેટને સિંક કરો. VM વિગતો, હોસ્ટ પ્લેસમેન્ટ, સ્ટોરેજ અને નેટવર્ક રૂપરેખાંકન જુઓ.',
        'card_assignment_title' => 'વપરાશકર્તા સોંપણી',
        'card_assignment_desc' => 'એસેટ્સ પર વપરાશકર્તાઓ સોંપો જેથી તમે હંમેશા જાણો કે કોની પાસે કયું ઉપકરણ છે. ફરી સોંપણીઓ ઑડિટ ટ્રેઇલમાં લૉગ થાય છે.',
        'locations_lead' => 'સ્થાનો ક્યાં છે?',
        'locations_body' => 'સ્થાનો હવે <strong>સિસ્ટમ &rarr; સ્થાનો</strong> પર રાખવામાં આવે છે, કારણ કે ફોર્મ (અને સમય જતાં લોકો અને ટિકિટ) તેમને એસેટની જેમ જ વાપરે છે. તે એ જ યાદી છે, અને દરેક એસેટે પોતાનું સ્થાન રાખ્યું છે. અહીંનું <strong>સેટિંગ્સ &rarr; સ્થાનો</strong> હજુ એ જ ટ્રી બતાવે છે અને સંપાદિત કરે છે, એટલે એડમિનિસ્ટ્રેટર ન હોય તેવા એસેટ મેનેજર પહેલાની જેમ તેની સંભાળ રાખી શકે છે - કોઈપણ જગ્યાએ કરેલો ફેરફાર બંનેમાં દેખાય છે.',
        'inventory_script_heading' => 'ઇન્વેન્ટરી સ્ક્રિપ્ટ',
    ],
