        'remove_confirm' => '{name} ને આ લીઝમાંથી સંપૂર્ણપણે ઉતારવી છે? ભૂલ માટે આનો ઉપયોગ કરો. જો તે લેસરને પાછી ગઈ હોય, તો તેના બદલે તેનું પરિણામ પરત કરેલ પર સેટ કરો જેથી રેકોર્ડ રહે.',
