        'deliveries' => 'ડિલિવરી',
        'deliveries_intro' => 'એક ડિલિવરી એટલે એક ઓર્ડર: તેનો સપ્લાયર, ઓર્ડર નંબર, ઇન્વોઇસ અને દસ્તાવેજો, દરેક આઇટમ માટે એક લાઇન સાથે. તેને બુક ઇન કરવાથી દરેક લાઇન સ્ટોકમાં જાય છે.',
