        'delivery_undo_what' => 'આ ડિલિવરીની જે દરેક લાઇન હજુ પૂર્વવત્ થઈ નથી તે બધી પૂર્વવત્ કરવી છે? મૂળ નોંધો ઇતિહાસમાં રહે છે.',
        'deliveries_search' => 'ઓર્ડર કે ઇન્વોઇસ નંબર, સપ્લાયર અથવા આઇટમ દ્વારા શોધો',
        'deliveries_count' => '{n} ડિલિવરી',
        'deliveries_none' => 'હજુ સુધી કોઈ ડિલિવરી નથી. ઘણી આઇટમ માટે નવું વાપરો, અથવા આઇટમ પર પ્રાપ્ત કરો.',
        'documents' => 'દસ્તાવેજો',
        'partly_undone' => 'આંશિક પૂર્વવત્',
        'h_delivery_created' => 'બુક ઇન કર્યું',
        'help_p8' => '<strong>ડિલિવરી.</strong> એક ઓર્ડર એટલે એક ડિલિવરી: <strong>ડિલિવરી → નવું</strong> સપ્લાયર, એક <strong>ઓર્ડર નંબર</strong> (વૈકલ્પિક), ઇન્વોઇસ નંબર અને તારીખ, અને દરેક આઇટમ માટે એક લાઇન લે છે - એક ઓર્ડર પર 10 માઉસ, 10 ટોનર અને 5 કીબોર્ડ. તેને બુક ઇન કરવાથી દરેક લાઇન પ્રાપ્ત થાય છે. ડિલિવરીના પેજ પર તેના <strong>દસ્તાવેજો</strong> (ઓર્ડર કન્ફર્મેશન, ઇન્વોઇસ) હોય છે, તમે તેની વિગતો સુધારી શકો છો - દરેક ફેરફાર નોંધાય છે - અને જો તે બે વાર બુક ઇન થઈ હોય તો <strong>ડિલિવરી પૂર્વવત્ કરો</strong> કરી શકાય છે. આઇટમ પર એક <strong>પ્રાપ્ત કરો</strong> એક-લાઇનની ડિલિવરી બનાવે છે, જેથી દરેક રસીદના કાગળો માટે એક ઠેકાણું રહે.',
        'help_heading' => 'કન્ઝ્યુમેબલ્સ',
        'help_intro' => '<strong>કન્ઝ્યુમેબલ્સ</strong> (હેડરમાં) એ એવી વસ્તુઓ છે જેને તમે એક-એક કરીને ટ્રૅક કરવાને બદલે ગણો છો - ટોનર, ફ્યુઝર, પેપર, માઉસ, કીબોર્ડ, RAM. નિયમ: જો તમે તેનો સીરિયલ નંબર લખી રાખો તો તે એસેટ છે; જો તમે તેને ગણો તો તે કન્ઝ્યુમેબલ છે. સ્ટોક તે કંપનીનો હોય છે જેમાં તમે કામ કરી રહ્યા છો.',
        'help_journey' => 'શરૂઆતથી અંત સુધી, જે ક્રમમાં થાય છે તે પ્રમાણે:',
        'help_step1' => '1. તમારી આઇટમ સેટ કરો',
        'help_step2' => '2. ક્યારે ઓર્ડર કરવો તે જાણો, અને ઓર્ડર કરો',
        'help_step3' => '3. ડિલિવરી લો',
        'help_step4' => '4. તેનો ઉપયોગ કરો',
        'help_step5' => '5. ભૂલો સુધારો',
        'help_step6' => '6. છાજલીઓ ગણો',
        'help_step7' => '7. શું ગુમ થયું તે જુઓ',
        'help_p1' => '<strong>આઇટમ અને પ્રકારો.</strong> <strong>નવું</strong> આઇટમ ઉમેરે છે: તેનો પ્રકાર, પાર્ટ નંબર, એકમ, સપ્લાયર, એકમ ખર્ચ, <strong>ફરી ઓર્ડર સ્તર</strong> અને <strong>ન્યૂનતમ</strong>. પ્રકારો <strong>સેટિંગ્સ → કન્ઝ્યુમેબલ્સ</strong>માં સેટ થાય છે, અને દરેક પ્રકારને <strong>સિસ્ટમ → કસ્ટમ ફીલ્ડ્સ → કન્ઝ્યુમેબલ્સ</strong>માં પોતાના ફીલ્ડ હોઈ શકે છે - ટોનર માટે પેજ યીલ્ડ, પેપર માટે વજન.',
        'help_p2' => '<strong>સ્ટોકનું હલનચલન.</strong> આઇટમ ખોલો, પછી ડિલિવરી <strong>પ્રાપ્ત કરો</strong> (જથ્થો, કિંમત, સપ્લાયર, ઇન્વોઇસ નંબર અને તારીખ - નવી કિંમતે ડિલિવરી નવી કિંમત બને છે), કોઈ વ્યક્તિને થોડું <strong>ઇશ્યૂ કરો</strong>, અથવા <strong>પરત</strong> લો. સ્ટોક ક્યારેય શૂન્યથી નીચે જતો નથી: જે છે તેથી વધુ ઇશ્યૂ કરવાનો ઇનકાર થાય છે. <strong>સમાયોજિત કરો</strong> (ખરાબ કે મળી આવેલા સ્ટોક માટે, કારણ સાથે) માટે સિસ્ટમ → ભૂમિકાઓમાં <em>કન્ઝ્યુમેબલ સ્ટોક સમાયોજિત કરો</em> પરવાનગી જોઈએ.',
        'help_p3' => '<strong>ટિકિટ સામે.</strong> ટિકિટ પર, <strong>લિંક કરો... → કન્ઝ્યુમેબલ્સ</strong> આ સ્ક્રીન ખોલે છે, જેમાં દરેક આઇટમની બાજુમાં <strong>ઇશ્યૂ કરો</strong> હોય છે, અને તે ટિકિટ અને તેના વિનંતી કરનારથી ભરેલું હોય છે. ઇશ્યૂ ટિકિટના ઇતિહાસમાં અને આઇટમના ઇતિહાસમાં દેખાય છે.',
        'help_p9' => '<strong>કન્ઝ્યુમેબલ્સનો ઉપયોગ.</strong> યાદીમાં ટિકિટ પર જમણું-ક્લિક કરો અને <strong>કન્ઝ્યુમેબલ વાપરો</strong> પસંદ કરો: ટિકિટની કંપનીની પહેલી 10 આઇટમ કેટલી સ્ટોકમાં છે તેની સાથે, અને એક શોધ બોક્સ. એક પસંદ કરવાથી ટિકિટ સામે, તેના વિનંતી કરનારને, એક ઇશ્યૂ થાય છે. ટિકિટની <strong>લિંક્સ</strong> દર્શાવે છે કે શું વપરાયું - ક્રોસ તેને કારણ સાથે પૂર્વવત્ કરે છે. રિક્વેસ્ટ ફોર્મ પૂછી શકે છે કે <strong>કયું</strong> કન્ઝ્યુમેબલ: ફોર્મ્સમાં <strong>કન્ઝ્યુમેબલ્સ</strong> પર <strong>લુકઅપ</strong> પ્રશ્ન ઉમેરો (તે પોર્ટલ પર પણ વાપરી શકાય છે). તેમાંથી નોંધાયેલી ટિકિટ માંગેલી આઇટમ ડૅશ્ડ પિલ તરીકે બતાવે છે - એક વાપરવા માટે તેના પર ક્લિક કરો. માંગવાથી સ્ટોક ક્યારેય હલતો નથી; ફક્ત વાપરવાથી હલે છે.',
        'help_p4' => '<strong>બધું નોંધાય છે.</strong> કોઈ સ્ટોક આંકડો લખતું નથી - દરેક રસીદ, ઇશ્યૂ, પરત અને સમાયોજન આઇટમના <strong>હલનચલન</strong>માં એક લાઇન હોય છે, જેમાં કોણે, ક્યારે, કોને, ટિકિટ અને તે સમયે તેનું મૂલ્ય હોય છે. ભૂલ <strong>પૂર્વવત્ કરો</strong> અને કારણ વડે સુધારાય છે: મૂળ નોંધ રહે છે, તેની બાજુમાં પૂર્વવત્ હોય છે. આઇટમમાં પોતાના ફેરફારો તેના <strong>ઇતિહાસ</strong> ટેબ પર છે.',
        'help_p5' => '<strong>ઓછું થઈ રહ્યું છે.</strong> <strong>ફરી ઓર્ડર સ્તર</strong> અથવા તેનાથી નીચે આઇટમ <em>ઓછો</em> તરીકે ચિહ્નિત થાય છે, Watchtower પર <em>ઓછો સ્ટોક</em> હેઠળ ગણાય છે, અને સેટિંગ્સ → કન્ઝ્યુમેબલ્સમાં પસંદ કરેલા લોકોને બેલ નોટિફિકેશન મળે છે - દર વખતે ઘટે ત્યારે એક વાર. <strong>ફરી ઓર્ડર</strong> ત્યાં પસંદ કરેલું રિક્વિઝિશન ફોર્મ ખોલે છે, જે આઇટમ, તેના સપ્લાયર અને સૂચવેલા જથ્થાથી ભરેલું હોય છે, અને તે તે ફોર્મની મંજૂરીઓમાંથી પસાર થાય છે.',
        'help_p6' => '<strong>સ્ટોક ગણતરી.</strong> એક શરૂ કરો, છાજલીઓ પર ફરો અને ખરેખર જે છે તે લખો. દરેક લાઇન તે ક્ષણે રેકોર્ડ મુજબ અપેક્ષિત જથ્થો, ગણેલો જથ્થો, તફાવત અને તેનું મૂલ્ય રાખે છે - 10 ની અપેક્ષા અને 8 મળે તો -2 નોંધાય છે. <strong>પૂરું કરો</strong> સ્ટોક સાચો કરે છે અને તેને <em>કન્ઝ્યુમેબલ સ્ટોક સમાયોજિત કરો</em> પરવાનગી જોઈએ; <strong>રદ કરો</strong> કંઈ બદલતું નથી.',
        'help_p7' => '<strong>તફાવતો</strong> દર્શાવે છે કે સ્ટોક ગણતરીમાં મહિના પ્રમાણે, પૈસા કે એકમોમાં, શું ઓછું કે વધારે મળ્યું, અને સૌથી વધુ ગુમ થતી આઇટમ. ઓછું અને વધારે અલગ બતાવાય છે, જેથી એક બીજાને છુપાવે નહીં.',
    ],
];
